INSERT INTO Service (id, title, slug, shortDescription, description, icon, "order", isActive, createdAt, updatedAt) VALUES
('svc_qiymetlendirme', 'Əmlakın Qiymətləndirilməsi', 'qiymetlendirme', 'Daşınmaz əmlakın bazar dəyərinin peşəkar şəkildə müəyyən edilməsi.', 'Daşınmaz əmlakın bazar dəyərinin peşəkar şəkildə müəyyən edilməsi. Müştərilərə satış, kirayə və investisiya qərarlarında dəqiq qiymət analizi təqdim olunur.', 'Calculator', 7, 1, datetime('now'), datetime('now')),
('svc_konsultasiya', 'Konsultasiya', 'konsultasiya', 'Daşınmaz əmlak alqı-satqısı, hüquqi məsələlər və bazar trendləri üzrə fərdi məsləhət xidməti.', 'Daşınmaz əmlak alqı-satqısı, hüquqi məsələlər və bazar trendləri üzrə fərdi məsləhət xidməti. Müştərilərə ən optimal qərarları qəbul etməkdə kömək edən ekspert dəstəyi.', 'MessageCircle', 8, 1, datetime('now'), datetime('now')),
('svc_a_frame_evler', 'A-frame Evlər', 'a-frame-evler-xidmeti', 'A-frame tipli evlərin layihələndirilməsi, tikintisi və satışına dair tam xidmət paketi.', 'A-frame tipli evlərin layihələndirilməsi, tikintisi və satışına dair tam xidmət paketi. Müasir dizayn, enerji səmərəliliyi və rahat yaşayış standartları ilə fərqlənir.', 'Triangle', 9, 1, datetime('now'), datetime('now')),
('svc_havalandirma', 'Havalandırma Sistemi', 'havalandirma-sistemi', 'Yaşayış və ofis məkanları üçün peşəkar havalandırma sistemlərinin quraşdırılması və texniki xidməti.', 'Yaşayış və ofis məkanları üçün peşəkar havalandırma sistemlərinin quraşdırılması və texniki xidməti. Təmiz hava, optimal temperatur və enerji qənaəti təmin olunur.', 'Wind', 10, 1, datetime('now'), datetime('now'));
